sys_script_client.script:
function onSubmit() {
    var action = g_form.getActionName();

    // Required on every submission from this view
    if (g_form.getValue('u_employee') == '') {
        alert('Please select an Employee.');
        return false;
    }
    if (g_form.getValue('u_due_date') == '') {
        alert('Please select a Due Date.');
        return false;
    }
    if (g_form.getValue('u_document_type') == '') {
        alert('Please select a Document Type.');
        return false;
    }
    if (g_form.getValue('u_status') == '') {
        alert('Please select a Status.');
        return false;
    }

    // Extra rule: Reject / Return require Reviewer Comments
    var rejectReturnActions = ['reject_document', 'return_document']; // confirm these against the "Action name" field on those UI Actions
    if (rejectReturnActions.indexOf(action) !== -1) {
        if (g_form.getValue('u_reviewer_comments') == '') {
            alert('Please provide Reviewer Comments before rejecting or returning this document.');
            return false;
        }
    }

    return true;
}
